import type { IUserModuleService, MedusaContainer } from "@medusajs/framework/types";
import { Modules } from "@medusajs/framework/utils";
import { listSellers } from "./sellers";
import { suggestSellerCode } from "./staff-profile";
import { profileOf, saveProfile, takenSellerCodes } from "./staff-profile-data";
import { invalidateStaffScope } from "./staff-scope";

/**
 * Codes are never typed: every one is generated by the system (owner's
 * decision). Two kinds share ONE namespace so a receipt never shows a code that
 * means two people:
 *  - a seller record's referral code (`deriveSellerCode`: "Ana García" → ANA),
 *    fixed for life because shared referral links carry it;
 *  - the code a panel user prints on receipts and lab tickets (staff profile):
 *    a counter seller's is their record's code; anyone else gets initials and a
 *    number (`suggestSellerCode`: "Carlos Méndez" → CM01).
 */

/** Every code in use: live seller records and staff profiles, except the given user's own. */
export async function takenCodes(container: MedusaContainer, exceptUserId?: string): Promise<Set<string>> {
  const [profiles, sellers] = await Promise.all([takenSellerCodes(container, exceptUserId), listSellers(container)]);
  return new Set([...profiles, ...sellers.filter((s) => !exceptUserId || s.user_id !== exceptUserId).map((s) => s.code)].map((c) => c.toUpperCase()));
}

/**
 * The user's receipt code, assigned now when they have none. A user linked to
 * a seller record takes that record's code (one person, one code); when
 * `fromSeller` is set, a different existing code is replaced by it.
 */
export async function ensureStaffCode(container: MedusaContainer, userId: string, opts: { fromSeller?: boolean } = {}): Promise<string | null> {
  const profile = await profileOf(container, userId);
  const sellers = await listSellers(container);
  const record = sellers.find((s) => s.user_id === userId) ?? null;
  if (profile.seller_code && !(opts.fromSeller && record && record.code !== profile.seller_code)) return profile.seller_code;

  const taken = await takenCodes(container, userId);
  let code: string;
  if (record && !taken.has(record.code)) {
    code = record.code;
  } else {
    const users = container.resolve<IUserModuleService>(Modules.USER);
    const user = await users.retrieveUser(userId).catch(() => null);
    if (!user) return profile.seller_code ?? null;
    // No name on the account (the owner is often email-only): initials from the email.
    const [first, last] = user.first_name || user.last_name
      ? [user.first_name ?? null, user.last_name ?? null]
      : String(user.email ?? "").split("@")[0].split(/[._-]+/).concat([null as unknown as string]);
    code = suggestSellerCode(first || null, last || null, [...taken]);
  }
  if (code === profile.seller_code) return code;
  try {
    await saveProfile(container, userId, { seller_code: code }, null);
  } catch (e) {
    // Lost a race for the code: the next view assigns another one.
    if ((e as Error).message === "seller_code_taken") return profile.seller_code ?? null;
    throw e;
  }
  invalidateStaffScope(userId);
  return code;
}
